=head2 Google::Cloud::Datastream::V1::DatastreamResources::SqlServerSslConfig

SQL Server SSL configuration information.

Inherits from L<Protobuf::Message>.

=head3 Accessors

=over 4

=item * C<< $msg->encryption_not_enforced() >> / C<< $msg->encryption_not_enforced($value) >>

Type: C<Message> (L<Google::Cloud::Datastream::V1::DatastreamResources::SqlServerSslConfig::EncryptionNotEnforced>)

If set, Datastream will not enforce encryption. If the DB server mandates
encryption, then connection will be encrypted but server identity will
not be authenticated.

=item * C<< $msg->basic_encryption() >> / C<< $msg->basic_encryption($value) >>

Type: C<Message> (L<Google::Cloud::Datastream::V1::DatastreamResources::SqlServerSslConfig::BasicEncryption>)

If set, Datastream will enforce encryption without authenticating server
identity. Server certificates will be trusted by default.

=item * C<< $msg->encryption_and_server_validation() >> / C<< $msg->encryption_and_server_validation($value) >>

Type: C<Message> (L<Google::Cloud::Datastream::V1::DatastreamResources::SqlServerSslConfig::EncryptionAndServerValidation>)

If set, Datastream will enforce encryption and authenticate server
identity.

=back

