Type: C<Message> (L<Google::Cloud::Datastream::V1::DatastreamResources::PostgresqlSslConfig::ServerVerification>)

 If this field is set, the communication will be encrypted with TLS
 encryption and the server identity will be authenticated.

=item * C<< $msg->server_and_client_verification() >> / C<< $msg->server_and_client_verification($value) >>

Type: C<Message> (L<Google::Cloud::Datastream::V1::DatastreamResources::PostgresqlSslConfig::ServerAndClientVerification>)

